def append_text_to_file(file_name, text_buffer, encoding="utf-8", overwrite=False):
    import os

    if os.path.exists(file_name) and not overwrite:
        return
    with open(file_name, "wb" if overwrite else "ab") as file:
        file.write(text_buffer.encode(encoding))
    return len(text_buffer.encode(encoding)) if overwrite else os.path.getsize(file_name)

