def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    def is_unique(cls_list):
        return len(cls_list) == len(set(cls_list))

    def get_minimal_base(cls, cls_list, other_bases):
        for cls_to_check in cls_list:
            if is_unique(cls_to_check):
                if (not other_bases or is_unique(other_bases)) and is_unique(cls_to_check + other_bases):
                    return cls_to_check
        return None

    minimal = None
    for cls in classes:
        minimal = get_minimal_base(cls, classes, minimal)

    if minimal is None:
        # If no minimal base could be found, just return the first class
        minimal = classes[0]

    return minimal

