def minimalBases(classes: List[Union[BaseClass, LeafClass, IntermediateClass]]) -> List[Union[BaseClass, LeafClass, IntermediateClass]]:
    # Find common base classes
    common_base = None
    for cls in classes:
        if common_base is None:
            common_base = cls
        else:
            intersection = common_base.get_common_base(cls)
            if intersection is None or intersection != common_base:
                common_base = intersection

    # Remove common classes from the list
    minimal_classes = [cls for cls in classes if cls != common_base]
    return minimal_classes

