def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1 or level == 0:
        return {k: v for k, v in d1.items() if k not in d2}
    return {
        k: v if k not in d2 or ( isinstance(v, dict) and all(difference(v, d2[k], level - 1).values()) and isinstance(k, str) and parent[k] != v) else None
        for k, v in d1.items()
    }

def difference(d1, d2, level=-1):
    result = {}
    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        elif level > -1:
            if isinstance(d1[key], dict):
                if isinstance(d2[key], dict) and level > 0:
                    res = difference(d1[key], d2[key], level - 1)
                    if res:
                        if result.get(key, None) is None:
                            result[key] = res
                        else:
                            for k, v in res.items():
                                result[key][k] = v
                else:
                    result[key] = d1[key]
            elif isinstance(d2[key], dict) and level > 0:
                result[key] = d2[key]
            else:
                if level > 0:
                    result[key] = d2[key]
                else:
                    result[key] = None
    for key in d2:
        if key not in d1:
            result[key] = d2[key]
    return result

