            # If no custom schema is specified, generate a default schema
            default_schema = {
                'resource': resource['kind'],
                'properties': {
                    'server': {'type': 'string'},
                    'port': {'type': 'integer'},
                    'headers': {'type': 'object'}
                }
            }
           (app.defs.observer_schemas).append(default_schema)

