def get_logical_path_map(inventory, version):
    logical_path_map = {}
    for folder, state_versions in inventory.items():
        for state_version, versions in state_versions.items():
            if version in versions:
                for content_file in versions[version]['content']:
                    logical_path_map[content_file['logical_path']] = {content_file}
                    for other_version in versions:
                        if version != other_version:
                            other_content_files = versions[other_version]['content']
                            for other_file in other_content_files:
                                if other_file['logical_path'] == content_file['logical_path']:
                                    logical_path_map[content_file['logical_path']].add(other_file)
    return logical_path_map

