def absorb(self, args):
    def handle_absorption(operation, a, b):
        if a == b:
            return a
        elif operation == "and":
            if a is None:
                return b
            elif b is None:
                return a
            else:
                return a & b
        elif operation == "or":
            if a is None:
                return b
            elif b is None:
                return a
            else:
                return a | b

    absorbed = []
    for a, b in args:
        absorbed.append(handle_absorption("and", a, b))
        absorbed.append(handle_absorption("or", a, b))

    return absorbed

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

            A & (A | B) = A, A | (A & B) = A

    Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if expr[0] == 'A' and expr[1] == '&':
            if expr[2][0] == 'A' and expr[2][1] == '|':
                result.append(expr[0])
            elif expr[2][0] == 'A' and expr[2][1] == '&':
                result.append(expr[0])
        elif expr[0] == 'A' and expr[1] == '|':
            if expr[2][0] == 'A' and expr[2][1] == '|':
                result.append(expr[0])
            elif expr[2][0] == 'A' and expr[2][1] == '&':
                result.append(expr[0])
    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    ret = [args[0]]
    for arg in args[1:]:
        if isinstance(arg, Expression):
            if isinstance(ret[-1], Expression) and ret[-1].isOr() and arg.isOr():
                ret[-1] = ret[-1] | arg
            elif isinstance(ret[-1], Expression) and ret[-1].isAnd() and arg.isAnd():
                ret[-1] = ret[-1] & arg
            else:
                ret.append(arg)
        else:
            ret.append(arg)
    return ret

