def validate_version_inventories(self, version_dirs: List[str]) -> bool:
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """

        # Check consistency of the detectibilty of patterns for all versions
        pattern_iter = self.pattern_check()

        consistent_patterns = True
        while pattern_iter:
            pattern = next(pattern_iter)
            if not self.__class__.pattern_score(p):
                consistent_patterns = False
                break

        # Check if each version has an inventory up to that point
        for version in version_dirs:
            version_path = os.path.join(self.inventories_root, version)
            if not os.path.exists(version_path):
                print(f"Version {version} does not have an inventory directory.")
                return False
            version_integrity = self.measure_integrity(version_path)
            if not version_integrity:
                print(f"Version {version} has an inventory directory but it is not consistent.")
                return False

        # Keep a record of any content digests different from those in the root inventory
        root_inventory_path = os.path.join(self.inventories_root, 'root')
        if os.path.exists(root_inventory_path):
            root_integrity = self.measure_integrity(root_inventory_path)
        else:
            root_integrity = False

        different_digests = set()
        for version in version_dirs:
            version_path = os.path.join(self.inventories_root, version)
            inventory_path = os.path.join(version_path, 'digest.digest')
            with open(inventory_path, 'r') as f:
                for line in f:
                    digest = line.strip()
                    if digest not in different_digests:
                        different_digests.add(digest)
                    else:
                        print(f"Duplicate digest {digest} found in version {version}.")

        if different_digests:
            print("Following different digests found in inventory directories:")
            print(different_digests)

        # Check whether all referenced sections from root inventory are present in all version inventories
        for section_name, section_elements in self.root_inventory.sections.items():
            section_inventories = []
            for version in version_dirs:
                version_path = os.path.join(self.inventories_root, version)
                inventory_path = os.path.join(version_path, section_name + '.digest')
                if os.path.exists(inventory_path):
                    with open(inventory_path, 'r') as f:
                        section_inventories.append(f.readlines())
            for section in section_elements:
                missing_in_versions = False
                for section_inventory in section_inventories:
                    if section in section_inventory:
                        missing_in_versions = True
                        break
                if not missing_in_versions:
                    print(f"Section {section} is not present in any version inventory.")

        # Validate each version's referential integrity
        for version in version_dirs:
            version_path = os.path.join(self.inventories_root, version)
            if not 0 < self.stage_check(version_path):
                print(f"Stage integrity check failed for version {version}.")
                return False
            if not self.pattern_check(version_path):
                print(f"Pattern integrity check failed for version {version}.")
                return False
            if not self.measure_integrity(version_path):
                print(f"Integrity check failed for version {version}.")
                return False

        # Validate content digests
        for version in version_dirs:
            version_path = os.path.join(self.inventories_root, version)
            inventory_path = os.path.join(version_path, 'digest.digest')
            with open(inventory_path, 'r') as f:
                for line in f:
                    digest = line.strip()
                    if digest not in self.root_inventory.digests:
                        print(f"Content digest {digest} is not present in the root inventory.")
                        return False

        root_inventory_path = os.path.join(self.inventories_root, 'root')
        if root_integrity:
            for digest in self.root_inventory.digests:
                if digest not in different_digests:
                    print(f"Content digest {digest} found in the root inventory but not in any version inventory.")
                    return False

        return True

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = self.get_inventory()
    digest_mappings = {}

    for version_dir in version_dirs:
        version_inventory = self.load_version_inventory(version_dir)
        if version_inventory is None:
            raise FileNotFoundError(f"Version inventory not found for {version_dir}")

        content_digests = set(version_inventory.content_digests)
        root_content_digests = set(root_inventory.content_digests)

        if content_digests != root_content_digests:
            digest_mappings[version_dir] = content_digests
            diff_digests = content_digests - root_content_digests
            if diff_digests:
                raise ValueError(f"Version inventory in {version_dir} contains different contents: {diff_digests}")

