    for subparser_name, parser in subparsers.items():
        # Check for argparse.Namespace in the method's signature
        if not issubclass(parser.parse_args, argparse.Namespace):
            raise ValueError("All subparsers must have Namespace as the return type")
        args = parser.parse_args(unparsed_arguments)
        result[subparser_name] = args
        remaining_args = [arg for arg in unparsed_arguments if arg not in args]
    return result, remaining_args

