def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    multiplier = {'B': 1, 'K': 1024, 'M': 1048576, 'G': 1073741824, 'T': 1099511627776}
    for unit in multiplier:
        if size[-1].upper() == unit:
            if size[:-1].isnumeric():
                return int(float(size[:-1]) * multiplier[unit])
            else:
                raise ValueError("Invalid input size for conversion to bytes.")

