def _replace_url_args(self, url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url_args:
        return url

    url_args = dict(url_args)
    url_parts = url.split('?')

    if len(url_parts) <= 1:
        return url

    url_parts[1] = '?'.join(f'{k}={v}' for k, v in url_args.items())


    return ''.join(url_parts)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if '?' in url:
        param_part, url = split(url)
    else:
        param_part, url = '', url

    replace_args = {}
    if ':' not in param_part:
        for name, value in url_args.items():
            if name.startswith(':'):
                if name[1:].isdigit():
                    replace_args[':{}]'.format(name[1:])] = value
                else:
                    replace_args[':{}='.format(name)] = value
            else:
                replace_args[name] = value

    return url + '&' + urllib.parse.urlencode(replace_args)

def _replace_url_args(url, url_args):
    url_parts = url.split('?')
    query_parts = []
    if len(url_parts) == 2:
        url, query = url_parts
    else:
        url, query = url, ''

    for pair in query.split('&'):
        altered = False
        for key in url_args:
            if key in pair:
                value = url_args[key]
                if altered:
                    url += '&'
                url += key + '=' + value
                altered = True
        if not altered:
            query_parts.append(pair)

    if altered:
        if query:
            query = '&'.join(query_parts)
        else:
            query = ''
        return url + '?' + query
    else:
        return url

