def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None:
        number = number.to_bytes(padding, byteorder='big', signed=False)
    else:
        number = number.to_bytes((number.bit_length() + 7) // 8, byteorder='big', signed=False)

    return ''.join(alphabet[byte] for byte in number)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Input must be a non-negative integer")

    str_num = []
    while number > 0:
        str_num.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding:
        str_num = str_num + [alphabet[0]] * padding

    return ''.join(str_num[::-1])

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None:
        number = number.lzfill(padding)

    return ''.join(iter(digits(number, base=len(alphabet))))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if padding is None:
        return ''.join(reversed(alphabet[number]))
    else:
        out = []
        while number > 0:
            out.append(alphabet[number % len(alphabet)])
            number //= len(alphabet)
        return ''.join(reversed(out)) + '_' * (padding - len(out))

