def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """

    def to_regex(key, parents):
        parent regex = parents[-1] if parents else r'(?s:\.)'
        match, filename = key.partition('(')
        parameters, _ = match.partition(')')
        if '.' in filename:
            if parameters:
                if parameters in parent regex:
                    raise ValueError(f"Conflicting parameters in multiple patterns")
                else:
                    parent regex += parent regex.replace('*', '[^\s/]*')
                    regex_keys.append([key, re.sub(fr'({parent_regex})(?![^\s/]*$)', fr'\1{parameters}', filename)])
                    parents.append(regex_keys[-1][1])
            else:
                parent regex += re.sub(r'(\.*?)', '[^\s/]*', filename)
            parents.pop()
        elif filename == '.*':
            if parameters:
                if parameters in parent regex:
                    raise ValueError(f"Conflicting parameters in multiple patterns")
                else:
                    regex_keys.append([key, re.sub(f'({parent_regex})(?![^\s/]*$)', fr'\1{parameters}', '.')])
                    parents.append(regex_keys[-1][1])
            else:
                parents.pop()
            parent regex += '[^\s]*'
            parents.pop()
        elif parameters and parameters not in parent regex:
            raise ValueError(f"Conflicting parameters in multiple patterns")

    regex_keys = []
    for key, value in item.items():
        to_regex(key, [key])
    return {key: value for key, value in regex_keys}

