        raise ValueError("Invalid platform value: %s" % platform)

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""

    process = subprocess.Popen(['git', 'ls-files', '--ignored'], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    output, error = process.communicate()

    if error:
        raise Exception(f"Error running git command: {error.decode('utf-8')}")

    file_names = output.decode('utf-8').strip().split('\n')
    sorted_ignored_files = sorted([f for f in file_names if f in ignored], key=len)

    return ','.join(sorted_ignored_files)

