def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()

    # Find all nodes
    all_nodes = set(graph)
    visited = set()

    # Use a queue to process nodes
    queue = deque()

    # Add all nodes connected to the source node to the queue
    for parent, child in graph.subject_objects(prop):
        if parent == 'source_node':
            queue.append(child)

    # BFS to find all roots
    while queue:
        node = queue.popleft()
        if node not in visited:
            visited.add(node)
            roots.add(node)

            # Add all nodes connected to the current node to the queue
            for parent, child in graph.subject_objects(prop):
