def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        if self.scale:
            return self.scale
        else:
            raise LenaValueError("The graph has no scale defined.")

    if not isinstance(other, (int, float)):
        raise ValueError("The scale must be a numeric value.")

    self.scale = other
    # Perform rescaling of all fields
    for field in self.fields:
        for val in field.values():
            try:
                if isinstance(val, LenaValue):
                    val.rescale(self.scale)
            except LenaValueError:
                raise LenaValueError("Error rescaling value in field '{}'".format(field.name), val)

def hist_to_graph(hist: Histogram, 
                  make_value: Optional[Callable[[float], float]] = None, 
                  get_coordinate: str = 'left', 
                  field_names: Tuple[str, str] = ('x', 'y'), 
                  scale: Optional[bool] = None) -> Graph:
    assert scale is not None or len(field_names) != 2, \
           "If the scale is None, you must provide the x and y field names."

    def set_value(bin_value):
        if make_value is not None:
            return make_value(bin_value)
        else:
            return bin_value.value

    if scale:
        plot_scale = hist.info['scale']
    else:
        plot_scale = None

    graph = Graph()
    x_axis = []
    y_axis = []

    for i, bin_data in enumerate(hist):
        bin_value = set_value(bin_data)

        if get_coordinate.lower() == 'left':
            if plot_scale:
                if field_names[0] == 'x' and plot_scale != 'log':
                    x_axis.append(bin_data * plot_scale)
                elif field_names[0] == 'x' and plot_scale == 'log':
                    x_axis.append(bin_data ** plot_scale)
                elif field_names[0] == 'y':
                    y_axis.append(bin_data * plot_scale)
                elif field_names[0] == 'y' and plot_scale == 'log':
                    y_axis.append(bin_data ** plot_scale)
            else:
                x_axis.append(bin_data)
                y_axis.append(bin_value)

        elif get_coordinate.lower() == 'right':
            if plot_scale:
                if field_names[0] == 'x' and plot_scale != 'log':
                    x_axis.append(bin_data * plot_scale)
                elif field_names[0] == 'x' and plot_scale == 'log':
                    x_axis.append(bin_data ** plot_scale)
                elif field_names[0] == 'y':
                    y_axis.append(bin_data * plot_scale)
                elif field_names[0] == 'y' and plot_scale == 'log':
                    y_axis.append(bin_data ** plot_scale)
            else:
                x_axis.append(bin_data + bin_data)
                y_axis.append(bin_value)

        elif get_coordinate.lower() == 'middle':
            if plot_scale:
                if field_names[0] == 'x' and plot_scale != 'log':
                    x_axis.append(bin_data * plot_scale)
                elif field_names[0] == 'x' and plot_scale == 'log':
                    x_axis.append(bin_data ** plot_scale)
                elif field_names[0] == 'y':
                    y_axis.append(bin_data * plot_scale)
                elif field_names[0] == 'y' and plot_scale == 'log':
                    y_axis.append(bin_data ** plot_scale)
            else:
                x_axis.append(bin_data/2)
                y_axis.append(bin_value)
    if len(y_axis) != len(field_names):
        raise ValueError("The length of the y-axis must be equal to the length of the field names.")
    graph.x = x_axis
    graph.y = y_axis
    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    if tentative:
        return True

    if not verifyObject(iface, candidate):
        return False

    for name, attr in methods(candidate):
        if not hasattr(candidate, name):
            raise Invalid("Object does not have method %s" % name)
        elif getattr(candidate, name) == getattr(iface, name):
            continue
        else:
            raise Invalid("Method %s does not have correct signature" % name)

    for name, attr in properties(candidate):
        if attr.implied_type and not isinstance(getattr(candidate, name), attr.implied_type):
            raise Invalid("Property %s does not have the correct type" % name)

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if not tentative:
        if not iface.providedBy(candidate):
            raise Invalid(f"Interface {iface.__name__} not provided by candidate {candidate}")

    def _check_methods(method):
        if not hasattr(candidate, 'providedBy'):
            raise Invalid("Cannot check methods of a non-implementing object")
        methodsinstance = candidate.providedBy()
        if hasattr(methodsinstance, method.__name__):
            methodinstance = getattr(methodsinstance, method.__name__)
            if not hasattr(candidate, method.__name__):
                raise Invalid(f"Method {method.__name__} not found in candidate")
            if vtype is None:
                if not inspect.isfunction(methodinstance):
                    raise Invalid(f"Method {method.__name__} is not a function")
                if not inspect.iscoroutinefunction(methodinstance):
                    raise Invalid(f"Method {method.__name__} is not a coroutine function")
                if method.__name__.startswith('_'):
                    raise Invalid(f"Method {method.__name__} starts with an underscore, which is not allowed for public methods")
            elif inspect.signature(methodinstance) != inspect.signature(vtype):
                raise Invalid(f"Method {method.__name__} does not match the expected signature")

    if vtype:
        #check methods of vtype if provided
        setattr(candidate, '_verify', _verify)
        try:
            candidate._verify(iface, candidate, tentative=True, vtype=None)
        except Invalid as e:
            candidate._verify = None
            raise Invalid(f"Invalid interface for {candidate}: {e}")

    #check all methods and attributes of candidate
    for name, value in candidate.__dict__.items():
        if name.startswith('_'):
            continue
        if inspect.ismethod(value) and name not in iface.implemented():
            raise Invalid(f"Method {name} not implemented by candidate {candidate}")
        if inspect.isfunction(value) and not hasattr(candidate, name):
            raise Invalid(f"Method {name} not found in candidate {candidate}")
        if hasattr(value, '__fget__'):
            if not inspect.isfunction(value.__fget__):
                raise Invalid(f"Function getter for attribute {name} is not a function")
            if not hasattr(candidate, name):
                raise Invalid(f"Attribute {name} not found in candidate")
            if vtype is None:
                if not inspect.signature(value.__fget__):
                    raise Invalid(f"Function getter for attribute {name} does not match the expected signature")
        if hasattr(value, '__fset__'):
            if not inspect.isfunction(value.__fset__):
                raise Invalid(f"Function setter for attribute {name} is not a function")
            if not hasattr(candidate, name):
                raise Invalid(f"Attribute {name} not found in candidate")
            if vtype is None:
                if not inspect.signature(value.__fset__):
                    raise Invalid(f"Function setter for attribute {name} does not match the expected signature")
        if hasattr(value, '__delete__'):
            if not inspect.isfunction(value.__delete__):
                raise Invalid(f"Function deleter for attribute {name} is not a function")
            if not hasattr(candidate, name):
                raise Invalid(f"Attribute {name} not found in candidate")
            if vtype is None:
                if not inspect.signature(value.__delete__):
                    raise Invalid(f"Function deleter for attribute {name} does not match the expected signature")
        if hasattr(value, '__setgetter__'):
            if not inspect.isfunction(value.__setgetter__):
                raise Invalid(f"Function setgetter for attribute {name} is not a function")
            if not hasattr(candidate, name):
                raise Invalid(f"Attribute {name} not found in candidate")
            if vtype is None:
                if not inspect.signature(value.__setgetter__):
                    raise Invalid(f"Function setgetter for attribute {name} does not match the expected signature")
        if hasattr(value, '__setsetter__'):
            if not inspect.isfunction(value.__setsetter__):
                raise Invalid(f"Function setsetter for attribute {name} is not a function")
            if not hasattr(candidate, name):
                raise Invalid(f"Attribute {name} not found in candidate")
            if vtype is None:
                if not inspect.signature(value.__setsetter__):
                    raise Invalid(f"Function setsetter for attribute {name} does not match the expected signature")
        if hasattr(value, '__delsetter__'):
            if not inspect.isfunction(value.__delsetter__):
                raise Invalid(f"Function delsetter for attribute {name} is not a function")
            if not hasattr(candidate, name):
                raise Invalid(f"Attribute {name} not found in candidate")
            if vtype is None:
                if not inspect.signature(value.__delsetter__):
                    raise Invalid(f"Function delsetter for attribute {name} does not match the expected signature")

    if hasattr(candidate, '_verify'):
        delattr(candidate, '_verify')

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    methods = iface.getMethods() or []
    attributes = iface.getAttributes() or []

    if tentative:
        for method in methods:
            candidate.implementation(method)
        for attr in attributes:
            candidate.provides(attr)
        return True

    for method in methods:
        if not hasattr(candidate, method) or not callable(getattr(candidate, method)):
            raise Invalid("Method '{}' not found in provided arguments".format(method))
        if vtype and not isinstance(getattr(candidate, method), vtype):
            raise Invalid("Method '{}' does not have the correct signature".format(method))

    for attr in attributes:
        if not hasattr(candidate, attr):
            raise Invalid("Attribute '{}' not found in provided arguments".format(attr))

    return True

def verifyObject(iface, candidate, tentative=False):
    if tentative:
        claim = candidate.providedBy
    else:
        claim = candidate.implementedBy if candidate.implementedBy else candidate.provides
    if iface.providedBy != claim and not tentative:
        raise Invalid("The candidate does not provide the interface specified by iface.")

    candidate_methods = set(dir(candidate))
    iface_methods = set(iface.implementedBy)

    missing_methods = iface_methods - candidate_methods
    if missing_methods:
        raise Invalid(f"The candidate does not implement the following methods: {list(missing_methods)}")

    missing_attributes = iface.attributes - candidate_attributes
    if missing_attributes:
        raise Invalid(f"The candidate does not implement the following attributes: {list(missing_attributes)}")

    return True

def verifyObject(iface, candidate, tentative=False):
    if tentative or not iface.providedBy(candidate):
        # if tentative, we only need to make sure candidate claims to provide iface
        pass
    else:
        # check if candidate defines all necessary methods
        required_methods = iface.requiredMethods()
        satisfied_methods = candidate.providedMethods()
        for method in required_methods:
            if method not in satisfied_methods:
                raise zope.interface.Invalid("Unable to verify object: missing method '" + method + "'")

        # check if candidate defines all necessary attributes
        required_attributes = iface.requiredAttributes()
        satisfied_attributes = candidate.providedAttributes()
        for attribute in required_attributes:
            if attribute not in satisfied_attributes:
                raise zope.interface.Invalid("Unable to verify object: missing attribute '" + attribute + "'")

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        getattr(candidate, iface)
        return False
    except AttributeError:
        pass

    if not tentative:
        raise ValueError(f"Failed to verify class {iface} with candidate {candidate}.")

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if tentative:
        return candidate.__class__.__bases__.count(iface.__dict__['__bases__'][0])
    else:
        return True

