def identify_request(self, request: RequestType):
        """Try to identify whether this is a Diaspora request.

        Try first public message. Then private message. The check if this is a legacy payload.
        """
        candidate = self.write(a=PUBLIC_MESSAGE + '\n\n' + request.text)
        if candidate is not None and 'NOT A DISBARIOR payload' not in candidate:
            return 'public_request'

        candidate = self.write(a=PRIVATE_MESSAGE + '\n\n' + request.text)
        if candidate is not None and 'NOT A DISBARIOR payload' not in candidate:
            return 'private_request'


        if 'legacy_payload' in request.data:
            return 'legacy_request'
        else:
            return 'unknown_request'

def identify_request(request: RequestType):
