    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # check for public message
    if request.data origen == "pmsg":
        return request

    # check for private message
    elif request.data origen == "pm":
        return request

    # check if it's a legacy payload
    elif request.data.startswith("legacy") or request.data.startswith("legacyismatch"):
        return request

