def find_tags(text: str, replacer: Callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code = False
    prev_char = None

    for char in text:
        if prev_char is not None and prev_char.isalnum() and char == '<':
            in_code = True
            tags.add(prev_char)
        elif prev_char is not None and prev_char.isalnum() and char == '>':
            in_code = False
        elif in_code:
            tags.add(char)

        if replacer and char == '[':
            replacer_expr_start = text.index('[')
            replacer_callback = re.compile(r'\]\((.*?)\)').match(text, replacer_expr_start)
            if replacer_callback:
                tags.add(['[', text[replacer_expr_start + 2:replacer_callback.end(1) - 1], ']'])
        prev_char = char

    return tags, text.replace('[' + text[0] + ']', '')

def find_tags(text: str, replacer: Callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    replaced_text = text
    is_code_block = False

    for i in range(len(text)):
        if text[i] == '<' and is_code_block:
            is_code_block = False
        elif text[i] == '<' and not is_code_block:
            start_tag = i
            is_code_block = True
        elif text[i] == '>' and is_code_block:
            is_code_block = False
            close_tag = i + 1
            text = text[:start_tag] + text[close_tag:]
        elif text[i] == '\n':
            is_code_block = False

        if not is_code_block and replacer:
            if text[i] == text[i].upper():
                if i == 0 or (i > 0 and text[i-1] != ' '):
                    tag_word = text[start_tag:close_tag]
                    if tag_word in replacer:
                        replaced_text = replaced_text[:start_tag] + replacer(tag_word) + replaced_text[close_tag:]
                        tags.add(tag_word)

    return tags, replaced_text

def find_tags(text: str, replacer: Callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """

    tags = set()
    stack = []
    ignore_code = False

    for match in re.finditer(r'<(.*?)>', text):
        tag = match.group(1).strip()
        if tag.startswith('/') and not ignore_code:
            tag = tag[1:]
            if stack:
                parent_tag = stack[-1]
                if tag == parent_tag:
                    stack.pop()
                else:
                    raise ValueError(f"Nested tag {tag} not allowed")
        elif not ignore_code:
            if tag.startswith('code'):
                ignore_code = True
            else:
                tags.add(tag)
                stack.append(tag)

    result_text = ''
    for match in re.finditer(r'<(.*?)>', text):
        tag = match.group(1).strip()
        if tag.startswith('/') and not ignore_code:
            tag = tag[1:]
            if stack:
                parent_tag = stack[-1]
                if tag == parent_tag:
                    stack.pop()
                else:
                    raise ValueError(f"Nested tag {tag} not allowed")
        elif not ignore_code:
            if replacer:
                tag_text = text[match.start():match.end()]
                result_text += replacer(tag_text)
            else:
                result_text += match.group(0)

    if ignore_code:
        result_text = result_text[4:]  # Remove the initial '<code>' tag

    return tags, result_text

def find_tags(text: str, replacer: Callable = None):
    tags = set()
    text_without_tags = text

    while True:
        match = re.search(r'`(.*?)`', text_without_tags)
        if match:
            tags.add(match.group(1))

            if replacer:
                text_without_tags = text_without_tags[:match.start()] + replacer(match.group(1)) + text_without_tags[match.end():]
        else:
            break

    return tags, text_without_tags

