def parse_diaspora_webfinger(document: str) -> Dict:
    if document.startswith('{'):
        # JSON format
        return json.loads(document)
    elif document.startswith('<'):
        # XRD format
        root = ET.fromstring(document)
        attributes = {'fingerprint': ET.SubElement(root, 'fingerprint').text, 
              'owner': ET.SubElement(root, 'owner').text, 
              'resource': ET.SubElement(root, 'resource').text}
        links = {}
        for link in root.findall('link'):
            links[link.attrib['rel']] = link.attrib['href']
        return {'attributes': attributes, 'links': links}
    else:
        raise ValueError("Unsupported format of Diaspora webfinger document")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """

    # Check if the document is valid JSON
    try:
        data = json.loads(document)
        # Validate the JSON structure as per Diaspora Webfinger specification
        if "subject" not in data or "links" not in data or not isinstance(data["links"], list):
            raise ValueError("Invalid JSON format for Diaspora webfinger")
        return data
    except json.JSONDecodeError:
        # Check if the document is valid XRD
        try:
            if "service" in document and "type" in document["service"]:
                if document["service"]["type"] == "http://webfinger.net/1.0/service/user":
                    data = {
                        "subject": document["service"]["href"],
                        "links": []
                    }
                    # Validate the XRD structure as per Diaspora Webfinger specification
                    if "links" not in data or not isinstance(data["links"], list):
                        raise ValueError("Invalid XRD format for Diaspora webfinger")
                    return data
                else:
                    raise ValueError("Invalid service type for Diaspora webfinger")
            else:
                raise ValueError("Invalid webfinger format")
        except (ValueError, KeyError):
            raise ValueError("Invalid webfinger format")

def parse_diaspora_webfinger(document: str) -> Dict:
    if 'application/json' in document:
        return json.loads(document)
    elif 'application/xrd+json' in document:
        root = ET.fromstring(document)
        return {
            'subject': root.attrib['subject'],
            'owner': root.attrib['owner'],
            'aliases': [a.text for a in root.findall('{http://webfinger.net/1.0/alias}alias')],
            '.links': [
                {
                    'rel': link.get('rel'),
                    'type': link.get('type'),
                    'href': link.get('href')
                }
                for link in root.findall('{http://webfinger.net/1.0/link}link')
            ]
        }
    else:
        raise ValueError("Unsupported format. Only JSON or XRD+JSON formats are supported.")

