def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("Spec content not provided")

        if 'required_fields' not in spec_content:
            raise IRValidatorException("Required fields not specified in spec file")

        for field in spec_content['required_fields']:
            if field not in spec_content:
                raise IRValidatorException(f"Field '{field}' not present in spec file")

        return spec_content

def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("Spec content cannot be None")

    if 'metadata' not in spec_content:
        raise IRValidatorException("Metadata is mandatory in the spec file")

    if 'name' not in spec_content['metadata']:
        raise IRValidatorException("Name is mandatory in the metadata section of the spec file")

    if 'version' not in spec_content['metadata']:
        raise IRValidatorException("Version is mandatory in the metadata section of the spec file")

    return spec_content

class AbstractElement:
    OCCURRENCES = None
    OCCURRENCES_PER_SET = None
    REQUIRED_ATTRIBS = None

    @classmethod
    def accepts(cls, Class, raiseexceptions, parent):
        pass

    @classmethod
    def is_valid(cls, klass):
        return cls in klass.VALID_ELEMENTS

    @classmethod
    def document_from_content(cls, spec_content=None):
        try:
            content = yaml.safe_load(spec_content)
        except yaml.YAMLError as e:
            raise IRValidatorException("Unable to parse YAML content: " + str(e))

        missing_fields = cls.validate(spec_content)
        if missing_fields:
            raise IRValidatorException("Missing mandatory fields in spec: " + ", ".join(missing_fields))

        return content

    @classmethod
    def validate(cls, spec_content):
        required_fields = cls.REQUIRED_ATTRIBS
        if required_fields and \
            not all(field in spec_content for field in required_fields):
            return [field for field in required_fields if field not in spec_content]
        return []

