def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    spec_path = os.path.join(plugin_dir, 'spec.yml')
    if not os.path.exists(spec_path):
        raise FileNotFoundError(f"Spec file not found at {spec_path}")

    with open(spec_path, 'r') as file:
        spec = yaml.safe_load(file)

    flatten_dict = {}
    def get_flatten_data(data, parent_key=''):
        if isinstance(data, dict):
            for key, value in data.items():
                get_flatten_data(value, key + '.' if parent_key else key)
        elif isinstance(data, list):
            for index, item in enumerate(data):
                get_flatten_data(item, parent_key + f'{index}.')
        elif data is not None:
            flatten_dict[parent_key] = data

    get_flatten_data(spec)
    return flatten_dict

